import React, { useEffect, useState } from 'react';
import { toast } from 'react-toastify';

import {
FiPlus,
FiTrash2,
FiEdit2,
FiImage,
FiUploadCloud,
FiX,
FiStar,
FiGrid,
} from 'react-icons/fi';

import api, {
getApiErrorMessage,
} from '../../services/api';

import AdminModal from '../common/AdminModal';
import AdminCard from '../common/AdminCard';

import { useLanguage } from '../../contexts/LanguageContext';

const AdminGallery = () => {

// =====================================================
// LANGUAGE
// =====================================================

const {
t,
language,
} = useLanguage();

// =====================================================
// STATE
// =====================================================

const [images, setImages] = useState([]);

const [loading, setLoading] = useState(true);

const [modalOpen, setModalOpen] = useState(false);

const [editingImage, setEditingImage] = useState(null);

const [submitting, setSubmitting] = useState(false);

const [imageFile, setImageFile] = useState(null);

const [imagePreview, setImagePreview] = useState('');

// =====================================================
// FORM DATA
// =====================================================

const [formData, setFormData] = useState({

// English
title_en: '',
category_en: '',
description_en: '',

// Khmer
title_km: '',
category_km: '',
description_km: '',

// Common
is_featured: false,
order: 0,

});

// =====================================================
// CATEGORY OPTIONS
// =====================================================

const categoryOptions = [
{
en: 'School Activities',
km: 'សកម្មភាពសាលា',
},
{
en: 'Classroom',
km: 'ថ្នាក់រៀន',
},
{
en: 'Graduation',
km: 'ពិធីបញ្ចប់ការសិក្សា',
},
{
en: 'Trips',
km: 'ដំណើរកម្សាន្ត',
},
{
en: 'Special Events',
km: 'ព្រឹត្តិការណ៍ពិសេស',
},
];

// =====================================================
// CURRENT LANGUAGE
// =====================================================

const isKhmer =
language === 'km' ||
language === 'kh';

// =====================================================
// GET LOCALIZED VALUE
// =====================================================

const getLocalizedValue = (
item,
field
) => {

if (!item) {
  return '';
}


if (isKhmer) {

  return (
    item[`${field}_km`] ||
    item[`${field}_en`] ||
    ''
  );

}


return (
  item[`${field}_en`] ||
  item[`${field}_km`] ||
  ''
);

};

// =====================================================
// FETCH IMAGES
// =====================================================

const fetchImages = async () => {

try {

  setLoading(true);


  const response = await api.get(
    '/api/gallery/'
  );


  setImages(
    Array.isArray(response.data)
      ? response.data
      : []
  );

} catch (error) {

  console.error(
    'Gallery error:',
    error
  );


  toast.error(
    getApiErrorMessage(
      error,
      t('gallery.loadFailed')
    )
  );

} finally {

  setLoading(false);

}

};

// =====================================================
// LOAD DATA
// =====================================================

useEffect(() => {

fetchImages();

}, []);

// =====================================================
// CLEAN OBJECT URL
// =====================================================

useEffect(() => {

return () => {

  if (
    imagePreview &&
    imagePreview.startsWith('blob:')
  ) {

    URL.revokeObjectURL(
      imagePreview
    );

  }

};

}, [imagePreview]);

// =====================================================
// RESET FORM
// =====================================================

const resetForm = () => {

setEditingImage(null);


setFormData({

  title_en: '',
  category_en: '',
  description_en: '',

  title_km: '',
  category_km: '',
  description_km: '',

  is_featured: false,
  order: 0,

});


if (
  imagePreview &&
  imagePreview.startsWith('blob:')
) {

  URL.revokeObjectURL(
    imagePreview
  );

}


setImageFile(null);

setImagePreview('');

};

// =====================================================
// OPEN ADD MODAL
// =====================================================

const handleAdd = () => {

resetForm();

setModalOpen(true);

};

// =====================================================
// CLOSE MODAL
// =====================================================

const handleCloseModal = () => {

setModalOpen(false);

resetForm();

};

// =====================================================
// INPUT CHANGE
// =====================================================

const handleInputChange = (e) => {

const {
  name,
  value,
  type,
  checked,
} = e.target;


setFormData((previous) => ({

  ...previous,

  [name]:
    type === 'checkbox'
      ? checked
      : value,

}));

};

// =====================================================
// IMAGE CHANGE
// =====================================================

const handleImageChange = (e) => {

const file =
  e.target.files?.[0];


if (!file) {
  return;
}


const allowedTypes = [
  'image/jpeg',
  'image/jpg',
  'image/png',
  'image/webp',
];


if (
  !allowedTypes.includes(
    file.type
  )
) {

  toast.error(
    t('gallery.invalidImage')
  );

  e.target.value = '';

  return;

}


if (
  file.size >
  5 * 1024 * 1024
) {

  toast.error(
    t('gallery.imageTooLarge')
  );

  e.target.value = '';

  return;

}


if (
  imagePreview &&
  imagePreview.startsWith('blob:')
) {

  URL.revokeObjectURL(
    imagePreview
  );

}


setImageFile(file);


setImagePreview(
  URL.createObjectURL(file)
);

};

// =====================================================
// REMOVE SELECTED NEW IMAGE
// =====================================================

const removeSelectedImage = () => {

if (
  imagePreview &&
  imagePreview.startsWith('blob:')
) {

  URL.revokeObjectURL(
    imagePreview
  );

}


setImageFile(null);


if (
  editingImage?.image_url
) {

  setImagePreview(
    editingImage.image_url
  );

} else {

  setImagePreview('');

}

};

// =====================================================
// VALIDATE FORM
// =====================================================

const validateForm = () => {

if (
  !formData.title_en.trim() &&
  !formData.title_km.trim()
) {

  toast.error(
    isKhmer
      ? 'សូមបញ្ចូលចំណងជើងយ៉ាងហោចណាស់មួយភាសា។'
      : 'Please enter a title in at least one language.'
  );

  return false;

}


if (
  !editingImage &&
  !imageFile
) {

  toast.error(
    t('gallery.imageRequired')
  );

  return false;

}


return true;

};

// =====================================================
// BUILD FORM DATA
// =====================================================

const buildPayload = () => {

const payload = new FormData();


// ===================================================
// ENGLISH
// ===================================================

payload.append(
  'title_en',
  formData.title_en || ''
);


payload.append(
  'category_en',
  formData.category_en || ''
);


payload.append(
  'description_en',
  formData.description_en || ''
);


// ===================================================
// KHMER
// ===================================================

payload.append(
  'title_km',
  formData.title_km || ''
);


payload.append(
  'category_km',
  formData.category_km || ''
);


payload.append(
  'description_km',
  formData.description_km || ''
);


// ===================================================
// COMMON
// ===================================================

payload.append(
  'is_featured',
  String(
    formData.is_featured
  )
);


payload.append(
  'order',
  String(
    Number(
      formData.order
    ) || 0
  )
);


// ===================================================
// IMAGE
// ===================================================

if (imageFile) {

  payload.append(
    'image_file',
    imageFile
  );

}


return payload;

};

// =====================================================
// SUBMIT
// =====================================================

const handleSubmit = async (e) => {

e.preventDefault();


if (!validateForm()) {
  return;
}


try {

  setSubmitting(true);


  const payload =
    buildPayload();


  // =================================================
  // UPDATE
  // =================================================

  if (editingImage) {

    await api.put(
      `/api/gallery/${editingImage.id}`,
      payload
    );


    toast.success(
      t(
        'gallery.updatedSuccess'
      )
    );

  }


  // =================================================
  // CREATE
  // =================================================

  else {

    await api.post(
      '/api/gallery/',
      payload
    );


    toast.success(
      t(
        'gallery.createdSuccess'
      )
    );

  }


  handleCloseModal();


  await fetchImages();

} catch (error) {

  console.error(
    'Gallery operation error:',
    error
  );


  toast.error(
    getApiErrorMessage(
      error,
      t(
        'common.operationFailed'
      )
    )
  );

} finally {

  setSubmitting(false);

}

};

// =====================================================
// EDIT
// =====================================================

const handleEdit = (image) => {

if (
  imagePreview &&
  imagePreview.startsWith('blob:')
) {

  URL.revokeObjectURL(
    imagePreview
  );

}


setEditingImage(image);


setFormData({

  title_en:
    image.title_en || '',

  category_en:
    image.category_en || '',

  description_en:
    image.description_en || '',


  title_km:
    image.title_km || '',

  category_km:
    image.category_km || '',

  description_km:
    image.description_km || '',


  is_featured:
    Boolean(
      image.is_featured
    ),

  order:
    Number(
      image.order
    ) || 0,

});


setImageFile(null);


setImagePreview(
  image.image_url || ''
);


setModalOpen(true);

};

// =====================================================
// DELETE
// =====================================================

const handleDelete = async (id) => {

const confirmed =
  window.confirm(
    t(
      'gallery.deleteConfirm'
    )
  );


if (!confirmed) {
  return;
}


try {

  await api.delete(
    `/api/gallery/${id}`
  );


  toast.success(
    t(
      'gallery.deletedSuccess'
    )
  );


  await fetchImages();

} catch (error) {

  console.error(
    'Delete image error:',
    error
  );


  toast.error(
    getApiErrorMessage(
      error,
      t(
        'gallery.deleteFailed'
      )
    )
  );

}

};

// =====================================================
// COUNTS
// =====================================================

const featuredCount =
images.filter(
(image) =>
image.is_featured
).length;

const categoryCount =
new Set(
images
.map((image) =>
isKhmer
? (
image.category_km ||
image.category_en
)
: (
image.category_en ||
image.category_km
)
)
.filter(Boolean)
).size;

// =====================================================
// RENDER
// =====================================================

return (

<div className="w-full">


  {/* =================================================
      HEADER
  ================================================== */}

  <div
    className="
      flex
      flex-col
      sm:flex-row
      sm:items-center
      sm:justify-between
      gap-4
      mb-6
    "
  >

    <div
      className="
        flex
        items-center
        gap-3
      "
    >

      <div
        className="
          w-10
          h-10
          bg-blue-900
          text-white
          rounded-xl
          flex
          items-center
          justify-center
          shadow-sm
        "
      >

        <FiImage size={18} />

      </div>


      <div>

        <h1
          className="
            text-xl
            md:text-2xl
            font-bold
            text-blue-900
          "
        >
          {t(
            'gallery.title'
          )}
        </h1>


        <p
          className="
            text-xs
            md:text-sm
            text-blue-400
            mt-1
          "
        >
          {t(
            'gallery.subtitle'
          )}
        </p>

      </div>

    </div>


    <button
      type="button"

      onClick={handleAdd}

      className="
        h-10
        px-4
        inline-flex
        items-center
        justify-center
        gap-2
        bg-red-600
        text-white
        rounded-lg
        text-sm
        font-semibold
        shadow-sm
        hover:bg-red-700
        hover:shadow-md
        transition-all
      "
    >

      <FiPlus size={17} />


      {t(
        'gallery.addImage'
      )}

    </button>

  </div>


  {/* =================================================
      SUMMARY
  ================================================== */}

  <div
    className="
      grid
      grid-cols-1
      sm:grid-cols-3
      gap-3
      mb-6
    "
  >


    {/* TOTAL */}

    <div
      className="
        bg-white
        border
        border-blue-200
        rounded-xl
        p-4
        shadow-sm
      "
    >

      <div
        className="
          flex
          items-center
          justify-between
        "
      >

        <div>

          <p
            className="
              text-xs
              text-blue-400
            "
          >
            {t(
              'gallery.totalImages'
            )}
          </p>


          <p
            className="
              text-2xl
              font-bold
              text-blue-900
              mt-1
            "
          >
            {images.length}
          </p>

        </div>


        <div
          className="
            w-10
            h-10
            bg-blue-50
            text-blue-900
            rounded-lg
            flex
            items-center
            justify-center
          "
        >

          <FiImage size={18} />

        </div>

      </div>

    </div>


    {/* FEATURED */}

    <div
      className="
        bg-white
        border
        border-red-100
        rounded-xl
        p-4
        shadow-sm
      "
    >

      <div
        className="
          flex
          items-center
          justify-between
        "
      >

        <div>

          <p
            className="
              text-xs
              text-blue-400
            "
          >
            {t(
              'gallery.featuredImages'
            )}
          </p>


          <p
            className="
              text-2xl
              font-bold
              text-red-600
              mt-1
            "
          >
            {featuredCount}
          </p>

        </div>


        <div
          className="
            w-10
            h-10
            bg-red-50
            text-red-600
            rounded-lg
            flex
            items-center
            justify-center
          "
        >

          <FiStar size={18} />

        </div>

      </div>

    </div>


    {/* CATEGORIES */}

    <div
      className="
        bg-white
        border
        border-blue-200
        rounded-xl
        p-4
        shadow-sm
      "
    >

      <div
        className="
          flex
          items-center
          justify-between
        "
      >

        <div>

          <p
            className="
              text-xs
              text-blue-400
            "
          >
            {t(
              'gallery.categories'
            )}
          </p>


          <p
            className="
              text-2xl
              font-bold
              text-blue-600
              mt-1
            "
          >
            {categoryCount}
          </p>

        </div>


        <div
          className="
            w-10
            h-10
            bg-blue-50
            text-blue-600
            rounded-lg
            flex
            items-center
            justify-center
          "
        >

          <FiGrid size={18} />

        </div>

      </div>

    </div>

  </div>


  {/* =================================================
      GALLERY CARD
  ================================================== */}

  <AdminCard
    className="
      border
      border-blue-200
      rounded-xl
      shadow-sm
      overflow-hidden
    "
  >

    <div
      className="
        px-5
        py-4
        border-b
        border-blue-200
      "
    >

      <h2
        className="
          text-sm
          font-bold
          text-blue-900
        "
      >
        {t(
          'gallery.allImages'
        )}
      </h2>


      <p
        className="
          text-xs
          text-blue-300
          mt-1
        "
      >

        {images.length}{' '}

        {
          images.length === 1
            ? t(
                'gallery.image'
              )
            : t(
                'gallery.images'
              )
        }{' '}

        {t(
          'gallery.found'
        )}

      </p>

    </div>


    {/* =================================================
        LOADING
    ================================================== */}

    {
      loading ? (

        <div
          className="
            min-h-[300px]
            flex
            items-center
            justify-center
          "
        >

          <div className="text-center">

            <div
              className="
                w-10
                h-10
                border-4
                border-blue-200
                border-t-blue-900
                rounded-full
                animate-spin
                mx-auto
              "
            />


            <p
              className="
                text-xs
                text-blue-300
                mt-3
              "
            >
              {t(
                'gallery.loading'
              )}
            </p>

          </div>

        </div>

      ) : images.length === 0 ? (

        <div
          className="
            min-h-[320px]
            flex
            items-center
            justify-center
            p-6
          "
        >

          <div className="text-center">

            <div
              className="
                w-16
                h-16
                bg-blue-50
                text-blue-900
                rounded-full
                flex
                items-center
                justify-center
                mx-auto
                mb-4
              "
            >

              <FiImage size={26} />

            </div>


            <h3
              className="
                text-base
                font-bold
                text-blue-900
              "
            >
              {t(
                'gallery.noImages'
              )}
            </h3>


            <p
              className="
                text-sm
                text-blue-400
                mt-1
                mb-4
              "
            >
              {t(
                'gallery.addFirstImage'
              )}
            </p>


            <button
              type="button"

              onClick={handleAdd}

              className="
                inline-flex
                items-center
                gap-2
                bg-red-600
                text-white
                px-4
                py-2.5
                rounded-lg
                text-sm
                font-semibold
                hover:bg-red-700
                transition
              "
            >

              <FiPlus />


              {t(
                'gallery.addImage'
              )}

            </button>

          </div>

        </div>

      ) : (

        <div
          className="
            p-4
            md:p-5
            grid
            grid-cols-1
            sm:grid-cols-2
            lg:grid-cols-3
            xl:grid-cols-4
            gap-4
          "
        >

          {
            images.map(
              (image) => {

                const title =
                  getLocalizedValue(
                    image,
                    'title'
                  );


                const description =
                  getLocalizedValue(
                    image,
                    'description'
                  );


                const category =
                  getLocalizedValue(
                    image,
                    'category'
                  );


                return (

                  <div
                    key={image.id}

                    className="
                      group
                      bg-white
                      border
                      border-blue-200
                      rounded-xl
                      overflow-hidden
                      shadow-sm
                      hover:shadow-lg
                      hover:-translate-y-1
                      transition-all
                      duration-300
                    "
                  >


                    {/* IMAGE */}

                    <div
                      className="
                        relative
                        w-full
                        h-[190px]
                        bg-blue-50
                        overflow-hidden
                      "
                    >

                      {
                        image.image_url ? (

                          <img
                            src={
                              image.image_url
                            }

                            alt={
                              title ||
                              t(
                                'gallery.image'
                              )
                            }

                            className="
                              w-full
                              h-full
                              object-cover
                              group-hover:scale-105
                              transition-transform
                              duration-500
                            "

                            onError={(e) => {

                              e.currentTarget.style.display =
                                'none';

                            }}
                          />

                        ) : null
                      }


                      <div
                        className="
                          absolute
                          inset-0
                          -z-10
                          flex
                          items-center
                          justify-center
                          bg-blue-50
                          text-blue-300
                        "
                      >

                        <FiImage size={35} />

                      </div>


                      {
                        image.is_featured && (

                          <div
                            className="
                              absolute
                              top-3
                              left-3
                              inline-flex
                              items-center
                              gap-1.5
                              px-2.5
                              py-1.5
                              bg-red-600
                              text-white
                              rounded-lg
                              text-[10px]
                              font-bold
                              shadow-sm
                            "
                          >

                            <FiStar
                              size={11}
                              className="fill-current"
                            />


                            {t(
                              'gallery.featured'
                            )}

                          </div>

                        )
                      }


                      {
                        category && (

                          <div
                            className="
                              absolute
                              bottom-3
                              left-3
                              max-w-[75%]
                              px-2.5
                              py-1.5
                              bg-blue-900/90
                              backdrop-blur-sm
                              text-white
                              rounded-lg
                              text-[10px]
                              font-semibold
                              truncate
                            "
                          >

                            {category}

                          </div>

                        )
                      }

                    </div>


                    {/* CONTENT */}

                    <div className="p-4">

                      <h3
                        className="
                          text-sm
                          font-bold
                          text-blue-900
                          truncate
                        "
                      >

                        {
                          title ||
                          t(
                            'gallery.untitledImage'
                          )
                        }

                      </h3>


                      {
                        description ? (

                          <p
                            className="
                              text-xs
                              text-blue-400
                              mt-1.5
                              line-clamp-2
                              leading-5
                              min-h-[40px]
                            "
                          >

                            {description}

                          </p>

                        ) : (

                          <p
                            className="
                              text-xs
                              text-blue-300
                              mt-1.5
                              min-h-[40px]
                            "
                          >
                            {t(
                              'gallery.noDescription'
                            )}
                          </p>

                        )
                      }


                      <div
                        className="
                          flex
                          items-center
                          justify-between
                          pt-3
                          mt-3
                          border-t
                          border-blue-200
                        "
                      >

                        <span
                          className="
                            text-[10px]
                            text-blue-300
                          "
                        >

                          {t(
                            'gallery.order'
                          )}:{' '}

                          {
                            image.order ??
                            0
                          }

                        </span>


                        <div
                          className="
                            flex
                            items-center
                            gap-2
                          "
                        >

                          <button
                            type="button"

                            onClick={() =>
                              handleEdit(
                                image
                              )
                            }

                            className="
                              w-8
                              h-8
                              flex
                              items-center
                              justify-center
                              bg-blue-50
                              text-blue-900
                              rounded-lg
                              hover:bg-blue-900
                              hover:text-white
                              transition
                            "

                            title={
                              t(
                                'common.edit'
                              )
                            }
                          >

                            <FiEdit2
                              size={14}
                            />

                          </button>


                          <button
                            type="button"

                            onClick={() =>
                              handleDelete(
                                image.id
                              )
                            }

                            className="
                              w-8
                              h-8
                              flex
                              items-center
                              justify-center
                              bg-red-50
                              text-red-600
                              rounded-lg
                              hover:bg-red-600
                              hover:text-white
                              transition
                            "

                            title={
                              t(
                                'common.delete'
                              )
                            }
                          >

                            <FiTrash2
                              size={14}
                            />

                          </button>

                        </div>

                      </div>

                    </div>

                  </div>

                );

              }
            )
          }

        </div>

      )
    }

  </AdminCard>


  {/* =================================================
      ADD / EDIT MODAL
  ================================================== */}

  <AdminModal
    isOpen={modalOpen}

    onClose={
      handleCloseModal
    }

    title={
      editingImage
        ? t(
            'gallery.editImage'
          )
        : t(
            'gallery.addImage'
          )
    }
  >

    <form
      onSubmit={
        handleSubmit
      }
    >

      <div className="space-y-5">


        {/* =================================================
            ENGLISH CONTENT
        ================================================== */}

        <div
          className="
            border
            border-blue-200
            rounded-xl
            overflow-hidden
          "
        >

          <div
            className="
              px-4
              py-3
              bg-blue-50
              border-b
              border-blue-200
            "
          >

            <h3
              className="
                text-sm
                font-bold
                text-blue-900
              "
            >
              English Content
            </h3>

          </div>


          <div className="p-4 space-y-4">


            {/* TITLE EN */}

            <div>

              <label
                className="
                  block
                  text-sm
                  font-semibold
                  text-blue-900
                  mb-1.5
                "
              >
                Image Title
              </label>


              <input
                type="text"

                name="title_en"

                value={
                  formData.title_en
                }

                onChange={
                  handleInputChange
                }

                placeholder="Enter image title"

                className="
                  w-full
                  h-11
                  px-3.5
                  border
                  border-blue-200
                  rounded-lg
                  text-sm
                  text-blue-900
                  outline-none
                  focus:border-blue-900
                  focus:ring-2
                  focus:ring-blue-900/10
                  transition
                "
              />

            </div>


            {/* CATEGORY EN */}

            <div>

              <label
                className="
                  block
                  text-sm
                  font-semibold
                  text-blue-900
                  mb-1.5
                "
              >
                Category
              </label>


              <select
                name="category_en"

                value={
                  formData.category_en
                }

                onChange={
                  handleInputChange
                }

                className="
                  w-full
                  h-11
                  px-3.5
                  border
                  border-blue-200
                  rounded-lg
                  bg-white
                  text-sm
                  text-blue-900
                  outline-none
                  focus:border-blue-900
                  focus:ring-2
                  focus:ring-blue-900/10
                "
              >

                <option value="">
                  Select category
                </option>


                {
                  categoryOptions.map(
                    (category) => (

                      <option
                        key={
                          category.en
                        }

                        value={
                          category.en
                        }
                      >
                        {
                          category.en
                        }
                      </option>

                    )
                  )
                }

              </select>

            </div>


            {/* DESCRIPTION EN */}

            <div>

              <label
                className="
                  block
                  text-sm
                  font-semibold
                  text-blue-900
                  mb-1.5
                "
              >
                Description
              </label>


              <textarea
                name="description_en"

                value={
                  formData.description_en
                }

                onChange={
                  handleInputChange
                }

                rows="3"

                placeholder="Enter image description"

                className="
                  w-full
                  px-3.5
                  py-3
                  border
                  border-blue-200
                  rounded-lg
                  text-sm
                  text-blue-900
                  resize-none
                  outline-none
                  focus:border-blue-900
                  focus:ring-2
                  focus:ring-blue-900/10
                  transition
                "
              />

            </div>

          </div>

        </div>


        {/* =================================================
            KHMER CONTENT
        ================================================== */}

        <div
          className="
            border
            border-red-100
            rounded-xl
            overflow-hidden
          "
        >

          <div
            className="
              px-4
              py-3
              bg-red-50
              border-b
              border-red-100
            "
          >

            <h3
              className="
                text-sm
                font-bold
                text-red-700
              "
            >
              មាតិកាភាសាខ្មែរ
            </h3>

          </div>


          <div className="p-4 space-y-4">


            {/* TITLE KM */}

            <div>

              <label
                className="
                  block
                  text-sm
                  font-semibold
                  text-blue-900
                  mb-1.5
                "
              >
                ចំណងជើងរូបភាព
              </label>


              <input
                type="text"

                name="title_km"

                value={
                  formData.title_km
                }

                onChange={
                  handleInputChange
                }

                placeholder="បញ្ចូលចំណងជើងរូបភាព"

                className="
                  w-full
                  h-11
                  px-3.5
                  border
                  border-blue-200
                  rounded-lg
                  text-sm
                  text-blue-900
                  outline-none
                  focus:border-blue-900
                  focus:ring-2
                  focus:ring-blue-900/10
                  transition
                "
              />

            </div>


            {/* CATEGORY KM */}

            <div>

              <label
                className="
                  block
                  text-sm
                  font-semibold
                  text-blue-900
                  mb-1.5
                "
              >
                ប្រភេទ
              </label>


              <select
                name="category_km"

                value={
                  formData.category_km
                }

                onChange={
                  handleInputChange
                }

                className="
                  w-full
                  h-11
                  px-3.5
                  border
                  border-blue-200
                  rounded-lg
                  bg-white
                  text-sm
                  text-blue-900
                  outline-none
                  focus:border-blue-900
                  focus:ring-2
                  focus:ring-blue-900/10
                "
              >

                <option value="">
                  ជ្រើសរើសប្រភេទ
                </option>


                {
                  categoryOptions.map(
                    (category) => (

                      <option
                        key={
                          category.km
                        }

                        value={
                          category.km
                        }
                      >
                        {
                          category.km
                        }
                      </option>

                    )
                  )
                }

              </select>

            </div>


            {/* DESCRIPTION KM */}

            <div>

              <label
                className="
                  block
                  text-sm
                  font-semibold
                  text-blue-900
                  mb-1.5
                "
              >
                ការពិពណ៌នា
              </label>


              <textarea
                name="description_km"

                value={
                  formData.description_km
                }

                onChange={
                  handleInputChange
                }

                rows="3"

                placeholder="បញ្ចូលការពិពណ៌នារូបភាព"

                className="
                  w-full
                  px-3.5
                  py-3
                  border
                  border-blue-200
                  rounded-lg
                  text-sm
                  text-blue-900
                  resize-none
                  outline-none
                  focus:border-blue-900
                  focus:ring-2
                  focus:ring-blue-900/10
                  transition
                "
              />

            </div>

          </div>

        </div>


        {/* =================================================
            DISPLAY ORDER
        ================================================== */}

        <div>

          <label
            className="
              block
              text-sm
              font-semibold
              text-blue-900
              mb-1.5
            "
          >
            {t(
              'gallery.displayOrder'
            )}
          </label>


          <input
            type="number"

            name="order"

            min="0"

            value={
              formData.order
            }

            onChange={(e) =>
              setFormData(
                (previous) => ({
                  ...previous,

                  order:
                    Number(
                      e.target.value
                    ) || 0,
                })
              )
            }

            className="
              w-full
              h-11
              px-3.5
              border
              border-blue-200
              rounded-lg
              text-sm
              text-blue-900
              outline-none
              focus:border-blue-900
              focus:ring-2
              focus:ring-blue-900/10
            "
          />

        </div>


        {/* =================================================
            IMAGE UPLOAD
        ================================================== */}

        <div>

          <label
            className="
              block
              text-sm
              font-semibold
              text-blue-900
              mb-1.5
            "
          >

            {
              editingImage
                ? t(
                    'gallery.changeImage'
                  )
                : t(
                    'gallery.uploadImage'
                  )
            }


            {
              !editingImage && (

                <span
                  className="
                    text-red-600
                  "
                >
                  {' '}*
                </span>

              )
            }

          </label>


          {
            !imagePreview ? (

              <label
                className="
                  min-h-[150px]
                  border-2
                  border-dashed
                  border-blue-200
                  rounded-xl
                  bg-blue-50
                  flex
                  flex-col
                  items-center
                  justify-center
                  cursor-pointer
                  hover:border-blue-400
                  transition-all
                "
              >

                <div
                  className="
                    w-11
                    h-11
                    bg-white
                    text-blue-900
                    rounded-xl
                    flex
                    items-center
                    justify-center
                    mb-2
                    shadow-sm
                  "
                >

                  <FiUploadCloud
                    size={21}
                  />

                </div>


                <p
                  className="
                    text-sm
                    font-semibold
                    text-blue-900
                  "
                >
                  {t(
                    'gallery.clickUpload'
                  )}
                </p>


                <p
                  className="
                    text-[11px]
                    text-blue-300
                    mt-1
                  "
                >
                  {t(
                    'gallery.imageFormats'
                  )}
                </p>


                <input
                  type="file"

                  accept="
                    image/jpeg,
                    image/jpg,
                    image/png,
                    image/webp
                  "

                  onChange={
                    handleImageChange
                  }

                  className="hidden"
                />

              </label>

            ) : (

              <div
                className="
                  relative
                  w-full
                  h-[220px]
                  bg-blue-50
                  rounded-xl
                  overflow-hidden
                  border
                  border-blue-200
                "
              >

                <img
                  src={
                    imagePreview
                  }

                  alt={
                    t(
                      'gallery.preview'
                    )
                  }

                  className="
                    w-full
                    h-full
                    object-cover
                  "
                />


                <button
                  type="button"

                  onClick={
                    removeSelectedImage
                  }

                  className="
                    absolute
                    top-3
                    right-3
                    w-8
                    h-8
                    bg-black/60
                    text-white
                    rounded-full
                    flex
                    items-center
                    justify-center
                    hover:bg-red-600
                    transition
                  "

                  title={
                    t(
                      'common.remove'
                    )
                  }
                >

                  <FiX size={15} />

                </button>


                <label
                  className="
                    absolute
                    left-3
                    bottom-3
                    inline-flex
                    items-center
                    gap-2
                    bg-white
                    text-blue-900
                    px-3
                    py-2
                    rounded-lg
                    shadow-md
                    text-xs
                    font-semibold
                    cursor-pointer
                    hover:bg-blue-900
                    hover:text-white
                    transition
                  "
                >

                  <FiUploadCloud />


                  {t(
                    'gallery.changeImage'
                  )}


                  <input
                    type="file"

                    accept="
                      image/jpeg,
                      image/jpg,
                      image/png,
                      image/webp
                    "

                    onChange={
                      handleImageChange
                    }

                    className="hidden"
                  />

                </label>

              </div>

            )
          }


          {
            editingImage &&
            !imageFile && (

              <p
                className="
                  text-[11px]
                  text-blue-300
                  mt-1.5
                "
              >
                {t(
                  'gallery.keepCurrentImage'
                )}
              </p>

            )
          }

        </div>


        {/* =================================================
            FEATURED
        ================================================== */}

        <label
          className={`
            flex
            items-center
            gap-3
            p-3.5
            border
            rounded-xl
            cursor-pointer
            transition-all

            ${
              formData.is_featured
                ? `
                  border-red-300
                  bg-red-50
                `
                : `
                  border-blue-200
                  bg-white
                `
            }
          `}
        >

          <input
            type="checkbox"

            name="is_featured"

            checked={
              formData.is_featured
            }

            onChange={
              handleInputChange
            }

            className="
              w-4
              h-4
              accent-red-500
            "
          />


          <div
            className="
              w-9
              h-9
              bg-red-50
              text-red-600
              rounded-lg
              flex
              items-center
              justify-center
            "
          >

            <FiStar size={16} />

          </div>


          <div>

            <p
              className="
                text-sm
                font-semibold
                text-blue-900
              "
            >
              {t(
                'gallery.featured'
              )}
            </p>


            <p
              className="
                text-[10px]
                text-blue-300
                mt-0.5
              "
            >
              {t(
                'gallery.featuredDescription'
              )}
            </p>

          </div>

        </label>

      </div>


      {/* =================================================
          FOOTER
      ================================================== */}

      <div
        className="
          mt-6
          pt-4
          border-t
          border-blue-200
          flex
          flex-col-reverse
          sm:flex-row
          items-stretch
          sm:items-center
          justify-end
          gap-3
        "
      >

        <button
          type="button"

          onClick={
            handleCloseModal
          }

          disabled={
            submitting
          }

          className="
            h-10
            px-4
            bg-white
            border
            border-blue-200
            text-blue-400
            rounded-lg
            text-sm
            font-semibold
            hover:bg-blue-50
            disabled:opacity-50
            disabled:cursor-not-allowed
            transition
          "
        >
          {t(
            'common.cancel'
          )}
        </button>


        <button
          type="submit"

          disabled={
            submitting
          }

          className="
            min-w-[130px]
            h-10
            px-5
            bg-red-600
            text-white
            rounded-lg
            text-sm
            font-semibold
            hover:bg-red-700
            disabled:opacity-50
            disabled:cursor-not-allowed
            transition
          "
        >

          {
            submitting
              ? editingImage
                ? t(
                    'gallery.updating'
                  )
                : t(
                    'gallery.uploading'
                  )
              : editingImage
              ? t(
                  'gallery.updateImage'
                )
              : t(
                  'gallery.addImage'
                )
          }

        </button>

      </div>

    </form>

  </AdminModal>

</div>

);

};

export default AdminGallery;
